{
  "contract": "NeoCypherpunk",
  "closure": {
    "site_function": "feeClaim",
    "site_call": ".call",
    "functions": [
      "feeClaim",
      "claimMarketingFees",
      "swapOnDemand",
      "_transfer"
    ],
    "justification": "These functions interact with 'pendingmarketingFees' and are reachable during the callback."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "feeClaim",
      "claimMarketingFees",
      "swapOnDemand",
      "_transfer"
    ],
    "nesting_bound": {
      "feeClaim": 1
    }
  },
  "phases": {
    "function": "feeClaim",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before .call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before .call",
      "to_marker": "after .call"
    },
    "post": {
      "name": "post",
      "from_marker": "after .call",
      "to_marker": "exit"
    },
    "linearization_point": "after .call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of marketing fees in-flight during callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingmarketingFees == _balances[address(this)] + inFlight",
    "stable_formula": "pendingmarketingFees == _balances[address(this)]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "pendingmarketingFees <= _balances[address(this)]",
    "rule": "The exposure invariant ensures that the pending marketing fees are always backed by the contract's balance, accounting for in-flight adjustments during callbacks."
  }
}
